 24	// Runtime is an owned runtime instance with explicit lifecycle.
 25	type Runtime struct {
 26		VM      *goja.Runtime
 27		Require *require.RequireModule
 28		Loop    *eventloop.EventLoop
 29		Owner   runtimeowner.Runner
 30		Values  map[string]any
 31	
 32		runtimeCtx       context.Context
 33		runtimeCtxCancel context.CancelFunc
 34	
 35		closeOnce sync.Once
 36		closerMu  sync.Mutex
 37		closers   []func(context.Context) error
 38		closing   bool
 39	}
 40	
 41	// Value returns runtime-scoped data produced during runtime setup.
 42	func (r *Runtime) Value(key string) (any, bool) {
 43		if r == nil || r.Values == nil || key == "" {
 44			return nil, false
 45		}
 46		value, ok := r.Values[key]
 47		return value, ok
 48	}
 49	
 50	// Context returns the runtime-owned lifecycle context.
 51	func (r *Runtime) Context() context.Context {
 52		if r == nil || r.runtimeCtx == nil {
 53			return context.Background()
 54		}
 55		return r.runtimeCtx
 56	}
 57	
 58	// AddCloser registers a cleanup hook that is executed before the runtime owner
 59	// and event loop are shut down.
 60	func (r *Runtime) AddCloser(fn func(context.Context) error) error {
 61		if r == nil {
 62			return fmt.Errorf("runtime is nil")
 63		}
 64		if fn == nil {
 65			return fmt.Errorf("runtime closer is nil")
 66		}
 67	
 68		r.closerMu.Lock()
 69		defer r.closerMu.Unlock()
 70	
 71		if r.closing {
 72			return fmt.Errorf("runtime is closing or closed")
 73		}
 74		r.closers = append(r.closers, fn)
 75		return nil
 76	}
 77	
 78	// Close shuts down runtime-owned resources.
 79	func (r *Runtime) Close(ctx context.Context) error {
 80		if r == nil {
 81			return nil
 82		}
 83	
 84		var retErr error
 85		r.closeOnce.Do(func() {
 86			r.closerMu.Lock()
 87			r.closing = true
 88			closers := append([]func(context.Context) error(nil), r.closers...)
 89			r.closers = nil
 90			r.closerMu.Unlock()
 91	
 92			if r.runtimeCtxCancel != nil {
 93				r.runtimeCtxCancel()
 94			}
 95			if r.VM != nil {
 96				runtimebridge.Delete(r.VM)
 97			}
 98	
 99			for i := len(closers) - 1; i >= 0; i-- {
100				if err := closers[i](ctx); err != nil {
101					retErr = errors.Join(retErr, err)
102				}
103			}
104			if r.Owner != nil {
105				if err := r.Owner.Shutdown(ctx); err != nil {
106					retErr = errors.Join(retErr, err)
107				}
108			}
109			if r.Loop != nil {
110				r.Loop.Stop()
111			}
112		})
113	
114		return retErr
115	}

