 16	// FactoryBuilder composes explicit module and runtime initializer configuration
 17	// before producing an immutable Factory.
 18	type FactoryBuilder struct {
 19		settings builderSettings
 20	
 21		modules                 []ModuleSpec
 22		runtimeModuleRegistrars []RuntimeModuleRegistrar
 23		runtimeInitializers     []RuntimeInitializer
 24		built                   bool
 25	}
