 37	func (e *ScanError) Error() string {
 38		if e == nil || len(e.Diagnostics) == 0 {
 39			return "jsverbs scan failed"
 40		}
 41		parts := make([]string, 0, len(e.Diagnostics))
 42		for _, diagnostic := range e.Diagnostics {
 43			location := diagnostic.Path
 44			if diagnostic.Symbol != "" {
 45				location += "#" + diagnostic.Symbol
 46			}
 47			if location == "" {
 48				location = "jsverbs"
 49			}
 50			parts = append(parts, fmt.Sprintf("%s: %s", location, diagnostic.Message))
 51		}
 52		return strings.Join(parts, "; ")
 53	}
