180	func (r *Registry) AddSharedSection(section *SectionSpec) error {
181		if r == nil {
182			return fmt.Errorf("registry is nil")
183		}
184		if section == nil {
185			return fmt.Errorf("shared section is nil")
186		}
187	
188		slug := cleanCommandWord(section.Slug)
189		if slug == "" {
190			return fmt.Errorf("shared section slug is empty")
191		}
192	
193		if r.SharedSections == nil {
194			r.SharedSections = map[string]*SectionSpec{}
195		}
196		if _, ok := r.SharedSections[slug]; ok {
197			return fmt.Errorf("duplicate shared section %q", slug)
198		}
199		for name, field := range section.Fields {
200			if field == nil {
201				return fmt.Errorf("shared section %q field %q is nil", slug, name)
202			}
203		}
204	
205		cloned := section.Clone()
206		cloned.Slug = slug
207		for name, field := range cloned.Fields {
208			if field == nil {
209				continue
210			}
211			if strings.TrimSpace(field.Name) == "" {
212				field.Name = name
213			}
214		}
215		r.SharedSections[slug] = cloned
216		r.SharedSectionOrder = append(r.SharedSectionOrder, slug)
217	
218		return nil
219	}
