230	func (r *Registry) ResolveSection(verb *VerbSpec, slug string) (*SectionSpec, bool) {
231		slug = cleanCommandWord(slug)
232		if slug == "" {
233			return nil, false
234		}
235		if verb != nil && verb.File != nil && verb.File.Sections != nil {
236			if section, ok := verb.File.Sections[slug]; ok && section != nil {
237				return section, true
238			}
239		}
240		if r == nil || r.SharedSections == nil {
241			return nil, false
242		}
243		section, ok := r.SharedSections[slug]
244		if !ok || section == nil {
245			return nil, false
246		}
247		return section, true
248	}
