   175	func (r *Registry) injectOverlay(moduleKey string, file *FileSpec, source string) string {
   176		functionNames := []string{}
   177		if file != nil {
   178			for _, fn := range file.Functions {
   179				functionNames = append(functionNames, fn.Name)
   180			}
   181			sort.Strings(functionNames)
   182		}
   183	
   184		var suffix strings.Builder
   185		suffix.WriteString("\n")
   186		suffix.WriteString(`globalThis.__glazedVerbRegistry = globalThis.__glazedVerbRegistry || {};` + "\n")
   187		suffix.WriteString(`globalThis.__glazedVerbRegistry["`)
   188		suffix.WriteString(moduleKey)
   189		suffix.WriteString(`"] = {`)
   190		for i, name := range functionNames {
   191			if i > 0 {
   192				suffix.WriteString(",")
   193			}
   194			suffix.WriteString(name)
   195			suffix.WriteString(`: typeof `)
   196			suffix.WriteString(name)
   197			suffix.WriteString(` === "function" ? `)
   198			suffix.WriteString(name)
   199			suffix.WriteString(` : undefined`)
   200		}
   201		suffix.WriteString("};\n")
   202	
   203		prelude := strings.Join([]string{
   204			`globalThis.__glazedVerbRegistry = globalThis.__glazedVerbRegistry || {};`,
   205			`globalThis.__package__ = globalThis.__package__ || function() {};`,
   206			`globalThis.__section__ = globalThis.__section__ || function() {};`,
   207			`globalThis.__verb__ = globalThis.__verb__ || function() {};`,
   208			`globalThis.doc = globalThis.doc || function() { return ""; };`,
   209			"",
   210		}, "\n")
   211	
   212		return injectPrelude(source, prelude) + suffix.String()
   213	}
   214	
   215	func injectPrelude(source, prelude string) string {
   216		trimmed := strings.TrimLeft(source, "\ufeff \t\r\n")
   217		if strings.HasPrefix(trimmed, `"use strict";`) || strings.HasPrefix(trimmed, `'use strict';`) {
   218			if idx := strings.Index(source, "\n"); idx >= 0 {
   219				return source[:idx+1] + prelude + source[idx+1:]
   220			}
   221		}
   222		return prelude + source
   223	}
