   212	func inferFieldFromParam(param ParameterSpec) *FieldSpec {
   213		field := &FieldSpec{Name: param.Name}
   214		if param.Rest {
   215			field.Argument = true
   216			field.Type = "stringList"
   217			return field
   218		}
   219		switch param.Kind {
   220		case ParameterIdentifier, ParameterUnknown:
   221			field.Type = "string"
   222			return field
   223		case ParameterObject, ParameterArray:
   224			return field
   225		}
   226	
   227		return field
   228	}
   229	
   230	func buildFieldDefinition(spec *FieldSpec) (*fields.Definition, error) {
   231		if spec == nil {
   232			return nil, fmt.Errorf("field spec is nil")
   233		}
   234		name := strings.TrimSpace(spec.Name)
   235		if name == "" {
   236			return nil, fmt.Errorf("field name is empty")
   237		}
   238		fieldType, err := glazedFieldType(spec)
   239		if err != nil {
   240			return nil, err
   241		}
   242		options := []fields.Option{}
   243		if spec.Help != "" {
   244			options = append(options, fields.WithHelp(spec.Help))
   245		}
   246		if spec.Short != "" {
   247			options = append(options, fields.WithShortFlag(spec.Short))
   248		}
   249		if spec.Required || (spec.Argument && spec.Default == nil) {
   250			options = append(options, fields.WithRequired(true))
   251		}
   252		if spec.Argument {
   253			options = append(options, fields.WithIsArgument(true))
   254		}
   255		if len(spec.Choices) > 0 {
   256			options = append(options, fields.WithChoices(spec.Choices...))
   257		}
   258		if spec.Default != nil {
   259			value, err := normalizeDefaultValue(spec.Default, fieldType)
   260			if err != nil {
   261				return nil, err
   262			}
   263			options = append(options, fields.WithDefault(value))
   264		}
   265		return fields.New(name, fieldType, options...), nil
   266	}
   267	
   268	func glazedFieldType(spec *FieldSpec) (fields.Type, error) {
   269		typeName := strings.ToLower(strings.TrimSpace(spec.Type))
   270		if typeName == "" && len(spec.Choices) > 0 {
   271			typeName = "choice"
   272		}
   273		switch typeName {
   274		case "", "string":
   275			return fields.TypeString, nil
   276		case "bool", "boolean":
   277			return fields.TypeBool, nil
   278		case "int", "integer":
   279			return fields.TypeInteger, nil
   280		case "float", "number":
   281			return fields.TypeFloat, nil
   282		case "stringlist", "list", "[]string":
   283			return fields.TypeStringList, nil
   284		case "choice":
   285			return fields.TypeChoice, nil
   286		case "choicelist":
   287			return fields.TypeChoiceList, nil
   288		default:
   289			return "", fmt.Errorf("unsupported field type %q", spec.Type
