   173			if err != nil {
   174				return registry, err
   175			}
   176			registry.Files = append(registry.Files, file)
   177			registry.filesByModule[file.ModulePath] = file
   178		}
   179	
   180		sort.Slice(registry.Files, func(i, j int) bool {
   181			return registry.Files[i].RelPath < registry.Files[j].RelPath
   182		})
   183	
   184		if err := registry.finalizeVerbs(); err != nil {
   185			return registry, err
