364	func (c *Command) RunIntoGlazeProcessor(ctx context.Context, parsedValues *values.Values, gp middlewares.Processor) error {
365		result, err := c.invoke(ctx, parsedValues)
366		if err != nil {
367			return err
368		}
369		rows, err := rowsFromResult(result)
370		if err != nil {
371			return err
372		}
373		for _, row := range rows {
374			if err := gp.AddRow(ctx, row); err != nil {
375				return err
376			}
377		}
378		return nil
379	}
