408	func renderTextResult(result interface{}) (string, error) {
409		if result == nil {
410			return "", nil
411		}
412		switch v := result.(type) {
413		case string:
414			return v, nil
415		case []byte:
416			return string(v), nil
417		case fmt.Stringer:
418			return v.String(), nil
419		}
420	
421		value := reflect.ValueOf(result)
422		if value.IsValid() && (value.Kind() == reflect.Slice || value.Kind() == reflect.Array) {
423			if value.Type().Elem().Kind() == reflect.Uint8 {
424				return string(value.Bytes()), nil
425			}
426		}
427	
428		b, err := json.MarshalIndent(result, "", "  ")
429		if err != nil {
430			return "", err
431		}
432		return string(b), nil
433	}
434	
435	func rowsFromResult(result interface{}) ([]types.Row, error) {
436		if result == nil {
437			return nil, nil
438		}
439		if row, ok := toRow(result); ok {
440			return []types.Row{row}, nil
441		}
442		value := reflect.ValueOf(result)
443		if value.Kind() == reflect.Slice || value.Kind() == reflect.Array {
444			rows := make([]types.Row, 0, value.Len())
445			for i := 0; i < value.Len(); i++ {
446				item := value.Index(i).Interface()
447				if row, ok := toRow(item); ok {
448					rows = append(rows, row)
449				} else {
450					rows = append(rows, types.NewRow(types.MRP("value", item)))
451				}
452			}
453			return rows, nil
454		}
455	
456		return []types.Row{types.NewRow(types.MRP("value", result))}, nil
457	}
458	
459	func prettySectionTitle(slug string) string {
460		return cases.Title(language.English).String(strings.ReplaceAll(slug, "-", " "))
461	}
462	
463	func toRow(value interface{}) (types.Row, bool) {
464		switch v := value.(type) {
465		case map[string]interface{}:
466			return types.NewRowFromMap(v), true
467		case map[string]string:
468			row := types.NewRow()
469			keys := make([]string, 0, len(v))
470			for key := range v {
471				keys = append(keys, key)
472			}
473			sort.Strings(keys)
474			for _, key := range keys {
475				row.Set(key, v[key])
476			}
477			return row, true
478		default:
479			rv := reflect.ValueOf(value)
480			if !rv.IsValid() || rv.Kind() != reflect.Map || rv.Type().Key().Kind() != reflect.String {
481				return nil, false
482			}
483			row := types.NewRow()
484			iter := rv.MapRange()
485			keys := []string{}
486			valuesByKey := map[string]interface{}{}
487			for iter.Next() {
488				key := iter.Key().String()
489				keys = append(keys, key)
490				valuesByKey[key] = iter.Value().Interface()
491			}
492			sort.Strings(keys)
493			for _, key := range keys {
494				row.Set(key, valuesByKey[key])
495			}
496			return row, true
497		}
498	}

