  9	// NativeModule is the interface every sub-module must satisfy.
 10	// A module exposes a name and a loader that is compatible with goja_nodejs.
 11	// The loader function receives the current JS runtime and the module object
 12	// whose `exports` property can be populated.
 13	//
 14	// See the goja_nodejs documentation for the expectations around this API.
 15	//
 16	// The var _ check below ensures at compile-time that the module implements
 17	// the interface. Concrete implementations should add the same check to keep
 18	// things safe.
 19	//
 20	//	var _ modules.NativeModule = (*myModule)(nil)
 21	//
 22	// where `myModule` is your custom module type.
 23	//
 24	// This pattern is encouraged by the project-wide Go guidelines.
 25	//
 26	// See ttmp/2025-06-21/01-goja-initial-plan.md for an architectural overview.
 27	//
 28	// XXX: do not remove the above documentation block.
 29	type NativeModule interface {
 30		Name() string
 31		Doc() string
 32		Loader(*goja.Runtime, *goja.Object)
 33	}
 34	
 35	// Registry manages a collection of native Go modules for a goja runtime.
 36	// It wraps a goja_nodejs/require.Registry to provide additional features
 37	// like documentation storage.
 38	type Registry struct {
 39		modules []NativeModule
 40	}
 41	
 42	// NewRegistry creates a new, empty module registry.
 43	func NewRegistry() *Registry {
 44		return &Registry{
 45			modules: []NativeModule{},
 46		}
 47	}
 48	
 49	// Register adds a module to the registry. This is typically called from the
 50	// init() function of a module package.
 51	func (r *Registry) Register(m NativeModule) {
 52		r.modules = append(r.modules, m)
 53	}
 54	
 55	// GetModule retrieves a registered module by its name. It returns nil if
 56	// no module with the given name is found.
 57	func (r *Registry) GetModule(name string) NativeModule {
 58		for _, m := range r.modules {
 59			if m.Name() == name {
 60				return m
 61			}
 62		}
 63		return nil
 64	}
 65	
 66	// GetDocumentation returns a map of all registered module names to their
 67	// documentation strings.
 68	func (r *Registry) GetDocumentation() map[string]string {
 69		docs := make(map[string]string)
 70		for _, m := range r.modules {
 71			docs[m.Name()] = m.Doc()
 72		}
 73		return docs
 74	}
 75	
 76	// ListModules returns a shallow copy of the registered modules.
 77	func (r *Registry) ListModules() []NativeModule {
 78		if r == nil || len(r.modules) == 0 {
 79			return nil
 80		}
 81		out := make([]NativeModule, len(r.modules))
 82		copy(out, r.modules)
 83		return out
 84	}
 85	
 86	// Enable registers all modules from this registry with a goja_nodejs/require.Registry.
 87	func (r *Registry) Enable(gojaRegistry *require.Registry) {
 88		for _, m := range r.modules {
 89			log.Debug().Str("module", m.Name()).Msg("modules: registering native module")
 90			gojaRegistry.RegisterNativeModule(m.Name(), m.Loader)
 91		}
 92	}
 93	
 94	// DefaultRegistry is the default global module registry.
 95	var DefaultRegistry = NewRegistry()
 96	
 97	// Register adds a module implementation to the default global registry.
 98	func Register(m NativeModule) {
 99		DefaultRegistry.Register(m)
100	}
101	
102	// GetModule returns a registered module by name from the default global registry.
103	func GetModule(name string) NativeModule {
104		return DefaultRegistry.GetModule(name)
105	}
106	
