 38	func (ctx *RuntimeContext) SetValue(key string, value any) {
 39		if ctx == nil || key == "" {
 40			return
 41		}
 42		if ctx.Values == nil {
 43			ctx.Values = map[string]any{}
 44		}
 45		ctx.Values[key] = value
 46	}
