  2	
  3	import (
  4		"bytes"
  5		"context"
  6		"fmt"
  7		"runtime"
  8		"strconv"
  9		"sync/atomic"
 10		"time"
 11	
 12		"github.com/dop251/goja"
 13	)
 14	
 15	type ownerCtxKey struct{}
 16	
 17	type ownerCtxValue struct {
 18		r   *runner
 19		gid uint64
 20	}
 21	
 22	type callResult struct {
 23		value any
 24		err   error
 25	}
 26	
 27	type runner struct {
 28		vm        *goja.Runtime
 29		scheduler Scheduler
 30		opts      Options
 31		closed    atomic.Bool
 32	}
 33	
 34	func NewRunner(vm *goja.Runtime, scheduler Scheduler, opts Options) Runner {
 35		if vm == nil {
 36			panic("runtimeowner: vm is nil")
 37		}
 38		if scheduler == nil {
 39			panic("runtimeowner: scheduler is nil")
 40		}
 41		if opts.Name == "" {
 42			opts.Name = "runtime"
 43		}
 44		return &runner{vm: vm, scheduler: scheduler, opts: opts}
 45	}
 46	
 47	func (r *runner) IsClosed() bool {
 48		if r == nil {
 49			return true
 50		}
 51		return r.closed.Load()
 52	}
 53	
 54	func (r *runner) Shutdown(context.Context) error {
 55		if r == nil {
 56			return nil
 57		}
 58		r.closed.Store(true)
 59		return nil
 60	}
 61	
 62	func (r *runner) Call(ctx context.Context, op string, fn CallFunc) (any, error) {
 63		if r == nil || fn == nil {
 64			return nil, fmt.Errorf("runtimeowner %s: nil runner or function", op)
 65		}
 66		if r.closed.Load() {
 67			return nil, ErrClosed
 68		}
 69		ctx = normalizeContext(ctx)
 70		var cancel context.CancelFunc
 71		if r.opts.MaxWait > 0 {
 72			if _, ok := ctx.Deadline(); !ok {
 73				ctx, cancel = context.WithTimeout(ctx, time.Duration(r.opts.MaxWait)*time.Millisecond)
 74				defer cancel()
 75			}
 76		}
 77	
 78		if r.isOwnerContext(ctx) {
 79			return r.invoke(ctx, op, fn)
 80		}
 81	
 82		resultCh := make(chan callResult, 1)
 83		accepted := r.scheduler.RunOnLoop(func(vm *goja.Runtime) {
 84			ownerCtx := r.withOwnerContext(ctx)
 85			select {
 86			case <-ownerCtx.Done():
 87				resultCh <- callResult{
 88					err: fmt.Errorf("runtimeowner %s: %w: %v", op, ErrCanceled, ownerCtx.Err()),
 89				}
 90				return
 91			default:
 92			}
 93			v, err := r.invoke(ownerCtx, op, fn)
 94			resultCh <- callResult{value: v, err: err}
 95		})
 96		if !accepted {
 97			return nil, fmt.Errorf("runtimeowner %s: %w", op, ErrScheduleRejected)
 98		}
 99	
100		select {
101		case <-ctx.Done():
102			return nil, fmt.Errorf("runtimeowner %s: %w: %v", op, ErrCanceled, ctx.Err())
103		case res := <-resultCh:
104			return res.value, res.err
105		}
106	}
107	
108	func (r *runner) Post(ctx context.Context, op string, fn PostFunc) error {
109		if r == nil || fn == nil {
110			return fmt.Errorf("runtimeowner %s: nil runner or function", op)
111		}
112		if r.closed.Load() {
113			return ErrClosed
114		}
115		ctx = normalizeContext(ctx)
116		var cancel context.CancelFunc
117		if r.opts.MaxWait > 0 {
118			if _, ok := ctx.Deadline(); !ok {
119				ctx, cancel = context.WithTimeout(ctx, time.Duration(r.opts.MaxWait)*time.Millisecond)
120			}
121		}
122	
123		select {
124		case <-ctx.Done():
125			if cancel != nil {
126				cancel()
127			}
128			return fmt.Errorf("runtimeowner %s: %w: %v", op, ErrCanceled, ctx.Err())
129		default:
130		}
131	
132		if r.isOwnerContext(ctx) {
133			if cancel != nil {
134				defer cancel()
135			}
136			r.invokePost(ctx, op, fn)
137			return nil
138		}
139	
140		accepted := r.scheduler.RunOnLoop(func(vm *goja.Runtime) {
141			if cancel != nil {
142				defer cancel()
143			}
144			ownerCtx := r.withOwnerContext(ctx)
145			select {
146			case <-ownerCtx.Done():
147				return
148			default:
149			}
150			r.invokePost(ownerCtx, op, fn)
151		})
152		if !accepted {
153			if cancel != nil {
154				cancel()
155			}
156			return fmt.Errorf("runtimeowner %s: %w", op, ErrScheduleRejected)
157		}
158		return nil
159	}
160	
161	func (r *runner) invoke(ctx context.Context, op string, fn CallFunc) (any, error) {
162		if !r.opts.RecoverPanics {
163			return fn(ctx, r.vm)
164		}
165	
166		var (
167			ret any
168			err error
169		)
170		func() {
171			defer func() {
172				if rec := recover(); rec != nil {
173					err = fmt.Errorf("runtimeowner %s: %w: %v", op, ErrPanicked, rec)
174					ret = nil
175				}
176			}()
177			ret, err = fn(ctx, r.vm)
178		}()
179		return ret, err
180	}
181	
182	func (r *runner) invokePost(ctx context.Context, op string, fn PostFunc) {
183		if r.opts.RecoverPanics {
184			defer func() {
185				_ = recover()
186			}()
187		}
188		fn(ctx, r.vm)
189	}
190	
191	func normalizeContext(ctx context.Context) context.Context {
192		if ctx == nil {
193			ctx = context.Background()
194		}
195		return ctx
196	}
197	
198	func (r *runner) withOwnerContext(ctx context.Context) context.Context {
199		return context.WithValue(ctx, ownerCtxKey{}, ownerCtxValue{
200			r:   r,
201			gid: currentGoroutineID(),
202		})
203	}
204	
205	func (r *runner) isOwnerContext(ctx context.Context) bool {
206		v, ok := ctx.Value(ownerCtxKey{}).(ownerCtxValue)
207		if !ok || v.r != r || v.gid == 0 {
208			return false
209		}
210		return v.gid == currentGoroutineID()
211	}
212	
213	type ownerContexter interface {
214		withOwnerContext(context.Context) context.Context
215	}
216	
217	// OwnerContext marks ctx as belonging to the current owner goroutine for this
218	// runner. It should only be used at known owner-thread entry points (for
219	// example, inside native module exports invoked directly by the VM).
220	func OwnerContext(r Runner, ctx context.Context) context.Context {
221		ctx = normalizeContext(ctx)
222		if oc, ok := r.(ownerContexter); ok {
223			return oc.withOwnerContext(ctx)
224		}
225		return ctx
226	}
227	
228	func currentGoroutineID() uint64 {
229		var buf [64]byte
230		n := runtime.Stack(buf[:], false)
231		parts := bytes.Fields(buf[:n])
232		// Expected prefix: "goroutine <id> ..."
233		if len(parts) < 2 {
234			return 0
235		}
236		id, err := strconv.ParseUint(string(parts[1]), 10, 64)
237		if err != nil {
238			return 0
239		}
240		return id
241	}

